#include "ramdisk.h"
#include <string.h>

/* The backing store. 48 KB on the F411 is comfortable; we have 128 KB SRAM. */
static uint8_t  ramdisk_buf[RAMDISK_BLK_NBR * RAMDISK_BLK_SIZ];
static uint32_t bytes_written;
static uint8_t  initialised;

void RAMDISK_Init(void)
{
    if (initialised) {
        return;
    }
    memset(ramdisk_buf, 0, sizeof(ramdisk_buf));
    bytes_written = 0;
    initialised = 1;
}

int RAMDISK_Read(uint8_t *buf, uint32_t blk_addr, uint16_t blk_len)
{
    if ((blk_addr + blk_len) > RAMDISK_BLK_NBR) {
        return -1;
    }
    memcpy(buf,
           &ramdisk_buf[blk_addr * RAMDISK_BLK_SIZ],
           (size_t)blk_len * RAMDISK_BLK_SIZ);
    return 0;
}

int RAMDISK_Write(const uint8_t *buf, uint32_t blk_addr, uint16_t blk_len)
{
    if ((blk_addr + blk_len) > RAMDISK_BLK_NBR) {
        return -1;
    }
    memcpy(&ramdisk_buf[blk_addr * RAMDISK_BLK_SIZ],
           buf,
           (size_t)blk_len * RAMDISK_BLK_SIZ);
    bytes_written += (uint32_t)blk_len * RAMDISK_BLK_SIZ;
    return 0;
}

uint32_t RAMDISK_GetBytesWritten(void)
{
    return bytes_written;
}

void RAMDISK_ResetCounter(void)
{
    bytes_written = 0;
}
